def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width/full-height nonzero lines are the panel separators.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def blocks(length, separators):
        result = []
        start = 0
        for p in separators:
            if p >= start:
                result.append((start, p))
                start = p + 1
        if start < length:
            result.append((start, length))
        return result

    rb = blocks(h, sep_rows)
    cb = blocks(w, sep_cols)
    out = [row[:] for row in grid]

    for color in range(1, 10):
        occupied = [(i, j) for i, (a, b) in enumerate(rb)
                    for j, (c, d) in enumerate(cb)
                    if any(grid[r][x] == color
                           for r in range(a, b) for x in range(c, d))]
        if not occupied:
            continue

        rlo, rhi = min(i for i, _ in occupied), max(i for i, _ in occupied)
        clo, chi = min(j for _, j in occupied), max(j for _, j in occupied)

        if rlo == rhi:
            if rhi + 1 < len(rb):
                rhi += 1
            elif rlo > 0:
                rlo -= 1
        if clo == chi:
            if chi + 1 < len(cb):
                chi += 1
            elif clo > 0:
                clo -= 1

        # Reflect the contents of this panel region across its central axes.
        for r in range(rb[rlo][0], rb[rhi][1]):
            for c in range(cb[clo][0], cb[chi][1]):
                if grid[r][c] != color:
                    continue
                ri = next(i for i, (a, b) in enumerate(rb) if a <= r < b)
                ci = next(j for j, (a, b) in enumerate(cb) if a <= c < b)
                rr = r - rb[ri][0]
                cc = c - cb[ci][0]
                for nri in {ri, rlo + rhi - ri}:
                    for nci in {ci, clo + chi - ci}:
                        nr = rb[nri][0] + (rr if nri == ri else rb[ri][1] - rb[ri][0] - 1 - rr)
                        nc = cb[nci][0] + (cc if nci == ci else cb[ci][1] - cb[ci][0] - 1 - cc)
                        if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 0:
                            out[nr][nc] = color
    return out
